/* @autogenerated */
package net.civeira.phylax.common.exception;

import java.time.Duration;
import java.util.Optional;

/**
 * Exception thrown when the operation needs a stronger or more recent authentication than the one
 * behind the current token (RFC 9470, step-up authentication).
 *
 * It is mapped to an HTTP 401 response with
 * {@code WWW-Authenticate: Bearer error="insufficient_user_authentication"}, carrying the
 * {@code acr_values} and, when the login is too old, the {@code max_age} the client must ask for
 * when it sends the user back to the authorization endpoint.
 */
public class StepUpRequiredException extends RuntimeException {
  private static final long serialVersionUID = -4182730159846602317L;

  private final transient Duration maxAge;

  /**
   * Constructs a {@code StepUpRequiredException} asking for a second factor.
   *
   * @param message the detail message explaining the reason for the exception
   */
  public StepUpRequiredException(final String message) {
    this(message, null);
  }

  /**
   * Constructs a {@code StepUpRequiredException} asking for a second factor no older than the given
   * age.
   *
   * @param message the detail message explaining the reason for the exception
   * @param maxAge maximum age of the authentication, null when any age is valid
   */
  public StepUpRequiredException(final String message, final Duration maxAge) {
    super(message);
    this.maxAge = maxAge;
  }

  /**
   * Maximum age of the authentication the client must request.
   *
   * @return the age, empty when any age is valid
   */
  public Optional<Duration> getMaxAge() {
    return Optional.ofNullable(maxAge);
  }
}
